import {
  actionTypesToEvents,
  createCardDeclaration,
  registerCardComponent,
} from "@pihanga2/core";

import {Component} from "./pageWithNavbar.component";
import {PAGE_WITH_NAVBAR_ACTION} from "./pageWithNavbar.type";

export * from "./pageWithNavbar.type";

const CARD_NAME = "shad/pageWithNavbar";

export const SdPageWithNavbar = createCardDeclaration(CARD_NAME);

registerCardComponent({
  name: CARD_NAME,
  component: Component,
  events: actionTypesToEvents(PAGE_WITH_NAVBAR_ACTION),
});

import {Menu} from "lucide-react";
import clsx from "clsx";
import {useEffect, useRef, useState} from "react";

import {Button} from "@/components/ui/button";
import {Sheet, SheetContent, SheetTrigger} from "@/components/ui/sheet";
import {Card, type PiCardProps} from "@pihanga2/core";
import {getIconElement} from "@/cards/icons";
import {ScreenSize, SCREEN_SIZE_ORDER, SCREEN_SIZE_WIDTHS} from "@/cards/types";
import type {
  PageWithNavbarEvents,
  PageWithNavbarProps,
  ResponsiveCardRef,
} from "./pageWithNavbar.type";
import type {SizeMap} from "@/cards/types";
import type {PiCardRef} from "@pihanga2/core";

import "./pageWithNavbar.css";

// ---------------------------------------------------------------------------
// Style override type — consumers can extend this to add Tailwind class names
// to any structural section of the layout.
// ---------------------------------------------------------------------------

export type ShadStyle = {
  window?: string;
  page?: string;
  header?: string;
  main?: string;
  footer?: string;
};

// ---------------------------------------------------------------------------
// Screen-size hook
// ---------------------------------------------------------------------------

function getCurrentScreenSize(): ScreenSize {
  const w = typeof window !== "undefined" ? window.innerWidth : 0;
  // Walk breakpoints from largest to smallest
  for (let i = SCREEN_SIZE_ORDER.length - 1; i >= 0; i--) {
    const size = SCREEN_SIZE_ORDER[i];
    if (w >= SCREEN_SIZE_WIDTHS[size]) return size;
  }
  return ScreenSize.XS;
}

function useScreenSize(): ScreenSize {
  const [size, setSize] = useState<ScreenSize>(getCurrentScreenSize);

  useEffect(() => {
    const handleResize = () => setSize(getCurrentScreenSize());
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return size;
}

// ---------------------------------------------------------------------------
// Responsive card-ref resolution
// ---------------------------------------------------------------------------

function isSizeMap(ref: ResponsiveCardRef): ref is SizeMap<PiCardRef> {
  return typeof ref === "object" && ref !== null;
}

/**
 * Resolve a {@link ResponsiveCardRef} to a concrete `PiCardRef` (or
 * `undefined`) for the given screen size.
 *
 * Uses a **mobile-first cascade**: the entry with the largest breakpoint
 * that is still ≤ `currentSize` wins; falls back to `default` otherwise.
 */
function resolveCardRef(
  ref: ResponsiveCardRef | undefined,
  currentSize: ScreenSize,
): PiCardRef | undefined {
  if (!ref) return undefined;
  if (!isSizeMap(ref)) return ref; // plain PiCardRef (string or PiCardDef)

  // Cascade: find the highest breakpoint that is ≤ current size
  const currentIdx = SCREEN_SIZE_ORDER.indexOf(currentSize);
  for (let i = currentIdx; i >= 0; i--) {
    const size = SCREEN_SIZE_ORDER[i];
    if (Object.prototype.hasOwnProperty.call(ref, size)) {
      const val = ref[size];
      // null means "explicitly hidden at this breakpoint"
      return val ?? undefined;
    }
  }
  // Fall back to the default entry
  return ref.default ?? undefined;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export const Component = (
  props: PiCardProps<PageWithNavbarProps<ShadStyle>, PageWithNavbarEvents>,
): React.ReactNode => {
  const {
    title,
    iconName,
    main,
    footer,
    navLinks = [],
    scrollResetKey,
    headerLeftCard,
    headerRightCard,
    style,
    onNavigateTo,
    cardName,
  } = props;

  const screenSize = useScreenSize();
  const cl = style ?? {};
  const mainRef = useRef<HTMLElement | null>(null);

  // Scroll main back to top when the logical "page" changes
  useEffect(() => {
    mainRef.current?.scrollTo({top: 0, behavior: "auto"});
  }, [scrollResetKey]);

  const resolvedLeftCard = resolveCardRef(headerLeftCard, screenSize);
  const resolvedRightCard = resolveCardRef(headerRightCard, screenSize);
  const hasNavLinks = navLinks.length > 0;

  // ------------------------------------------------------------------
  // Sub-components
  // ------------------------------------------------------------------

  /** Title section: optional icon + text */
  function TitleSection({className}: {className?: string}) {
    const IconEl = iconName ? getIconElement(iconName) : undefined;
    return (
      <div className={clsx("title-section", className)}>
        {IconEl && <IconEl className="title-icon" aria-hidden />}
        <span className="title-text">{title}</span>
      </div>
    );
  }

  /** Nav bar rendered on medium screens and above */
  function NavMd() {
    return (
      <nav className="nav-md" aria-label="Main navigation">
        <TitleSection />
        {navLinks.map((el) => (
          <Button
            key={el.id}
            onClick={() => onNavigateTo({id: el.id})}
            variant="link"
            className="nav-link"
          >
            {el.title ?? capitalize(el.id)}
          </Button>
        ))}
      </nav>
    );
  }

  /** Hamburger trigger that opens a slide-out sheet on small screens */
  function NavSm() {
    return (
      <Sheet>
        <SheetTrigger asChild>
          <Button
            variant="outline"
            size="icon"
            className="shrink-0 md:hidden"
            aria-label="Toggle navigation menu"
          >
            <Menu className="h-5 w-5" aria-hidden />
          </Button>
        </SheetTrigger>
        <SheetContent side="left">
          <nav className="nav-sm" aria-label="Mobile navigation">
            <TitleSection />
            {navLinks.map((el) => (
              <Button
                key={el.id}
                onClick={() => onNavigateTo({id: el.id})}
                variant="link"
                className="nav-link"
              >
                {el.title ?? capitalize(el.id)}
              </Button>
            ))}
          </nav>
        </SheetContent>
      </Sheet>
    );
  }

  // ------------------------------------------------------------------
  // Layout
  // ------------------------------------------------------------------

  return (
    <div className={clsx("window", cl.window)} data-pihanga={cardName}>
      <div className={clsx("page", cl.page)}>
        {/* ── Header ─────────────────────────────────────────────── */}
        <header className={clsx("header", cl.header)}>
          {/* Medium+ nav (title + links) */}
          <NavMd />

          {/* Small-screen hamburger (only when there are nav links) */}
          {hasNavLinks && <NavSm />}

          {/* On small screens with no nav links, show the title inline.
              Wrap in a plain div so md:hidden isn't overridden by the
              .title-section CSS class that sets display:inline-flex. */}
          {!hasNavLinks && (
            <div className="md:hidden">
              <TitleSection />
            </div>
          )}

          {/* Push action cards to the right */}
          <div className="header-actions">
            {resolvedLeftCard && (
              <Card cardName={resolvedLeftCard} parentCard={cardName} />
            )}
            {resolvedRightCard && (
              <Card cardName={resolvedRightCard} parentCard={cardName} />
            )}
          </div>
        </header>

        {/* ── Main ───────────────────────────────────────────────── */}
        <main className={clsx("main", cl.main)} ref={mainRef}>
          <Card cardName={main} parentCard={cardName} />
        </main>

        {/* ── Footer (optional) ──────────────────────────────────── */}
        {footer && (
          <footer className={clsx("footer", cl.footer)}>
            <Card cardName={footer} parentCard={cardName} />
          </footer>
        )}
      </div>
    </div>
  );
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function capitalize(str: string): string {
  if (!str) return "";
  return str.charAt(0).toLocaleUpperCase() + str.slice(1);
}

/* ============================================================
   Outermost wrapper — centres the page horizontally
   ============================================================ */
.window {
  display: flex;
  width: 100%;
  height: 100%;
  justify-content: center;
}

/* ============================================================
   Page layout: flex column — header / main / footer
   (.window must have height:100% and html/body/#root must
   have height:100% for this to fill the viewport correctly)
   ============================================================ */
.page {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: 100%;
  width: 100%;
}

/* ============================================================
   Header
   ============================================================ */
.header {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 1rem;
  /* gap-4 */
  border-bottom: 1px solid var(--border);
  /* border-b */
  background-color: var(--background);
  /* bg-(--background) */
  padding-left: 1rem;
  /* px-4 */
  padding-right: 1rem;
  padding-top: 0.75rem;
  /* py-3 */
  padding-bottom: 0.75rem;
}

@media (min-width: 768px) {

  /* md:px-6 */
  .header {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

/* Title section (icon + text) */
.title-section {
  display: inline-flex;
  /* inline-flex */
  align-items: center;
  /* items-center */
  gap: 0.5rem;
  /* gap-2 */
}

.title-section .title-icon {
  height: 1.5rem;
  /* h-6 */
  width: 1.5rem;
  /* w-6 */
  flex-shrink: 0;
  /* shrink-0 */
}

.title-section .title-text {
  font-size: 1.125rem;
  /* text-lg */
  line-height: 1.75rem;
  font-weight: 600;
  /* font-semibold */
  color: var(--foreground);
  /* text-(--foreground) */
}

/* Medium-and-above horizontal nav */
.nav-md {
  display: none;
  /* hidden */
}

@media (min-width: 768px) {

  /* md:flex */
  .nav-md {
    display: flex;
    flex-direction: row;
    /* flex-row */
    align-items: center;
    /* items-center */
    gap: 1.25rem;
    /* gap-5 */
  }
}

@media (min-width: 1024px) {

  /* lg:gap-6 */
  .nav-md {
    gap: 1.5rem;
  }
}

.nav-md .nav-link {
  color: var(--muted-foreground);
  /* text-(--muted-foreground) */
  /* transition-colors */
  transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms;
  padding-left: 0;
  /* px-0 */
  padding-right: 0;
}

.nav-md .nav-link:hover {
  color: var(--foreground);
  /* hover:text-(--foreground) */
}

/* Small-screen slide-out nav content */
.nav-sm {
  display: grid;
  /* grid */
  gap: 1.5rem;
  /* gap-6 */
  font-size: 1.125rem;
  /* text-lg */
  line-height: 1.75rem;
  font-weight: 500;
  /* font-medium */
  padding: 1rem;
  /* p-4 */
}

.nav-sm .nav-link {
  color: var(--muted-foreground);
  /* text-(--muted-foreground) */
  justify-content: flex-start;
  /* justify-start */
  padding-left: 0;
  /* px-0 */
  padding-right: 0;
  font-size: 1.125rem;
  /* text-lg */
  line-height: 1.75rem;
}

.nav-sm .nav-link:hover {
  color: var(--foreground);
  /* hover:text-(--foreground) */
}

/* Right-aligned action cards area */
.header-actions {
  margin-left: auto;
  /* ml-auto */
  display: flex;
  /* flex */
  align-items: center;
  /* items-center */
  gap: 0.5rem;
  /* gap-2 */
}

@media (min-width: 1024px) {

  /* lg:gap-4 */
  .header-actions {
    gap: 1rem;
  }
}

/* ============================================================
   Main — scrollable content area
   ============================================================ */
.main {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background-color: var(--background);
  /* bg-(--background) */
  padding: 1rem;
  /* p-4 */
  padding-top: 0.5rem;
  /* py-2 */
  padding-bottom: 0.5rem;
}

@media (min-width: 768px) {

  /* md:p-8 md:py-4 */
  .main {
    padding: 2rem;
    padding-top: 1rem;
    padding-bottom: 1rem;
  }
}

/* ============================================================
   Footer (optional)
   ============================================================ */
.footer {
  flex-shrink: 0;
  background-color: var(--background);
  /* bg-(--background) */
  color: var(--muted-foreground);
  /* text-(--muted-foreground) */
  padding-left: 1rem;
  /* px-4 */
  padding-right: 1rem;
  padding-top: 0.5rem;
  /* py-2 */
  padding-bottom: 0.5rem;
}

@media (min-width: 768px) {

  /* md:px-8 md:py-4 */
  .footer {
    padding-left: 2rem;
    padding-right: 2rem;
    padding-top: 1rem;
    padding-bottom: 1rem;
  }
}

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";
import type {SizeMap} from "@/cards/types";

export const PAGE_WITH_NAVBAR_CARD = "pageWithNavbar";
export const PageWithNavbar = createCardDeclaration<
  PageWithNavbarProps,
  PageWithNavbarEvents
>(PAGE_WITH_NAVBAR_CARD);

export const PAGE_WITH_NAVBAR_ACTION = registerActions(PAGE_WITH_NAVBAR_CARD, [
  "navigate_to",
]);

export const onPageWithNavbarNavigateTo =
  createOnAction<PageWithNavbarNavigateToEvent>(
    PAGE_WITH_NAVBAR_ACTION.NAVIGATE_TO,
  );

/**
 * A card reference that can optionally vary by screen size.
 *
 * Pass a plain `PiCardRef` string to always show the same card, or a
 * {@link SizeMap} to show different cards (or none) at each breakpoint.
 *
 * @example
 * // Always show the same card
 * headerRightCard: "myAccountCard"
 *
 * // Show on md and above only
 * headerRightCard: { [ScreenSize.MD]: "myAccountCard" }
 *
 * // Different card per breakpoint
 * headerLeftCard: {
 *   [ScreenSize.XS]: "mobileSearchCard",
 *   [ScreenSize.MD]: "desktopSearchCard",
 * }
 */
export type ResponsiveCardRef = PiCardRef | SizeMap<PiCardRef>;

export type PageWithNavbarProps<S = unknown> = {
  /** Page title displayed in the header. */
  title: string;

  /**
   * Name of an icon registered via {@link registerIcon} in `icons.ts`.
   * When provided, the icon is rendered next to the title in the header.
   */
  iconName?: string;

  /** The main content card. */
  main: PiCardRef;

  /**
   * Optional footer card.
   * When omitted the footer row is not rendered.
   */
  footer?: PiCardRef;

  /**
   * Navigation links rendered in the header nav bar.
   * On small screens they are collapsed behind a hamburger menu.
   */
  navLinks?: NavLink[];

  /**
   * When this value changes the main content area scrolls back to the top.
   * Set it to any string that is unique per logical "page load" — typically
   * the URL or ID of the currently loaded resource (e.g. "foo.xml").
   */
  scrollResetKey?: string;

  /**
   * Optional card shown on the left side of the header actions area.
   * Supports size-dependent rendering via {@link ResponsiveCardRef}.
   */
  headerLeftCard?: ResponsiveCardRef;

  /**
   * Optional card shown on the right side of the header actions area.
   * Supports size-dependent rendering via {@link ResponsiveCardRef}.
   */
  headerRightCard?: ResponsiveCardRef;

  /** Additional style overrides passed through to the component. */
  style?: S;

  /** Additional CSS class names applied to the outermost wrapper. */
  className?: string;
};

export type NavLink = {
  id: string;
  title?: string;
};

export type PageWithNavbarNavigateToEvent = {id: string};

export type PageWithNavbarEvents = {
  onNavigateTo: PageWithNavbarNavigateToEvent;
};
